    f.at("office");result=f.run();need(result.ok&&result.value->command&&result.value->command->kind=="deliver_message","actual local original recipient receives original typed command");const auto& delivery=std::get<TaskCommand>(result.value->command->data);need(delivery.context.provider_actor_id=="recipient"&&delivery.offer_id=="letter","delivery retains original task and recipient");f.common.state().roles.find("receiver")->actor_id="replacement";result=f.run();need(result.ok&&!result.value->command&&result.value->transition->wait_reason=="MessageRecipientUnavailable","replacement cannot receive private letter");f.common.state().roles.find("receiver")->actor_id="recipient";f.view.locally_occupied_actor_ids={"recipient"};result=f.run();need(result.ok&&!result.value->command,"other conversation prevents local recipient command");f.view.locally_occupied_actor_ids.clear();f.policy.message_addresses.clear();result=f.run();need(result.ok&&!result.value->command&&result.value->transition->wait_reason=="MessageRecipientAddressUnknown","no address policy never scans world roles");f.policy.message_addresses.push_back({"letter","receiver"});
    f.common.state().inventories.find("bag:courier")->lots[0].owner={Owner::Kind::actor,"courier",{}};result=f.run();need(result.ok&&!result.value->command,"private lookalike letter cannot satisfy Task custody");f.common.state().inventories.find("bag:courier")->lots[0].owner={Owner::Kind::task,"task:5",{}};f.tasks.tasks.find("task:5")->status="ready";f.at("square");result=f.run();need(result.ok&&result.value->command->kind=="report_offer","delivered task returns original report command");f.common.state().roles.find("report")->actor_id="replacement";result=f.run();need(result.ok&&!result.value->command,"private issuer cannot be substituted at report");f.common.state().roles.find("report")->actor_id="sender";f.tasks.tasks.find("task:5")->deadline_tick=0;result=f.run();need(result.ok&&result.value->command->kind=="cancel_task","past original late grace chooses legitimate cancellation");
    auto* definition=f.tasks_catalog.offers.find("letter");definition->template_id="escort";definition->goal.actor_id="protected";definition->goal.destination_place_id="office";auto* task=f.tasks.tasks.find("task:5");task->status="active";task->deadline_tick=15;task->escort.emplace();result=f.run();need(result.ok&&!result.value->command&&result.value->transition->wait_reason=="EscortPersonNotFollowing","escort never recruits protected actor without original party");PartyRecord party;party.id="party";party.leader_id="courier";party.members={"courier","protected"};f.common.state().parties.insert(party.id,party);result=f.run();need(result.ok&&result.value->command->kind=="move_local","existing original escort party continues through Travel");f.at("office");result=f.run();need(result.ok&&!result.value->command&&result.value->transition->wait_reason=="EscortArrivalPending","arrival proposal does not forge Task success");task->escort->failure="EscortPersonLost";task->status="ready";task->deadline_tick=0;f.at("square");result=f.run();need(result.ok&&result.value->command->kind=="report_offer","failed escort retains original zero-reward late reporting rule");f.view.interaction_busy=true;result=f.run();need(result.ok&&!result.value->command,"participant conversation occupancy preserved");f.view.interaction_busy=false;task->assignee="other";need(!f.run().ok,"other actor Task cannot be adopted");
